const r32=id=>rank(id),oldStat=stats;stats=function(eq=state.equipment){const s=oldStat(eq);if(!state.cls)return s;if(state.cls==='war'&&state.guardTurns>0)s.reduction=Math.min(.52,s.reduction+.02*r32('w32c'));if(state.cls==='cleric'&&state.hp<s.h*.5)s.manaRegen=Math.min(10,s.manaRegen+.2*r32('c32b'));return s;};
const oldSkill=skillData;skillData=function(k){const s=oldSkill(k);if(state.cls==='mage'&&state.mana<stats().mana*.35)s.mana=Math.max(1,Math.ceil(s.mana*(1-.04*r32('m32b'))));if(state.cls==='cleric'&&s.heal)s.heal=Math.min(.24,s.heal*(1+.05*r32('c32a')));return s;};
const oldImpact=impact11;impact11=function(side,n,crit,cast,s){const cls=state.cls,d=state.voc27,procs=d?.procs||0,oldHP=state.hp,oldServants=state.necro30?.servants?.length||0;let bonus=0,energy=0;const live=combat32()&&state.active&&n>0;
 if(live&&side==='hero'){if(cls==='war'&&hasStatus('enemy','bleed'))bonus+=.03*r32('w32b');if(cls==='ranger'){if(crit)energy+=3*r32('r32a');if(!cast&&Math.abs(enemyPoint(gameNow28()).x-pos.x)>=.75*range11())bonus+=.04*r32('r32c');}if(cls==='mage'&&cast&&(hasStatus('enemy','burn')||hasStatus('enemy','freeze')))bonus+=.03*r32('m32a');if(cls==='necro'&&!oldServants)energy+=2*r32('n32c');}
 if(live&&side==='enemy'&&cls==='ranger'&&Math.abs(enemyPoint(gameNow28()).x-pos.x)<range11()*.55)bonus-=.03*r32('r32b');
 const out=oldImpact(side,Math.max(0,Math.round(n*(1+bonus))),crit,cast,s);const data=state.voc27;if(live&&data){if(side==='enemy'&&cls==='war'&&state.hp<oldHP)energy+=3*r32('w32a');if(energy)data.energy=Math.min(100,(data.energy||0)+energy);if(side==='hero'&&data.procs>procs){if(cls==='mage')state.mana=Math.min(s.mana,state.mana+Math.round(s.mana*.02*r32('m32c')));if(cls==='cleric')state.hp=Math.min(s.h,state.hp+Math.round(s.h*.01*r32('c32c')));if(cls==='necro'&&!(state.subclass===2&&oldServants))for(const a of state.necro30?.servants||[])a.left+=r32('n32a');}}return out;};
